import React from "react";
import ReactSpeedometer from "react-d3-speedometer";

function RiskMeter({ score = 0 }) {
  return (
    <div style={{ textAlign: "center" }}>
      <h2>Food Risk Indicator</h2>

      <ReactSpeedometer
        minValue={0}
        maxValue={100}
        value={score}
        segments={3}
        segmentColors={[
          "#22c55e",
          "#facc15",
          "#ef4444"
        ]}
        needleColor="black"
        currentValueText="Risk Score: ${value}"
        width={500}
        height={300}
      />
    </div>
  );
}

export default RiskMeter;
